    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n = read_ints()[0]
    a = read_ints()
    edges = [tuple(read_ints()) for _ in range(n - 1)]

    # Build the tree
    tree = [[] for _ in range(n + 1)]
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Calculate the size of each subtree
    size = [0] * (n + 1)
    def dfs(node, parent):
        size[node] = 1
        for neighbor in tree[node]:
            if neighbor != parent:
                size[node] += dfs(neighbor, node)
        return size[node]

    dfs(1, -1)

    # Calculate the maximum sum of pleasantness for each subtree
    max_sum = [0] * (n + 1)
    def dfs2(node, parent):
        max_sum[node] = a[node - 1]
        for neighbor in tree[node]:
            if neighbor != parent:
                dfs2(neighbor, node)
                max_sum[node] += max(0, max_sum[neighbor])
        return max_sum[node]

    dfs2(1, -1)

    # Calculate the best possible sum for each node
    best = [0] * (n + 1)
    def dfs3(node, parent):
        best[node] = max_sum[node]
        for neighbor in tree[node]:
            if neighbor != parent:
                # Remove the contribution of the neighbor subtree
                max_sum[node] -= max(0, max_sum[neighbor])
                # Calculate the best sum for the neighbor
                dfs3(neighbor, node)
                # Add back the contribution of the neighbor subtree
                max_sum[node] += max(0, max_sum[neighbor])
                # Update the best sum for the current node
                best[node] = max(best[node], max_sum[node] + max(0, best[neighbor]))

    dfs3(1, -1)

    # Find the maximum sum of pleasantness for two non-intersecting subtrees
    result = -float('inf')
